/* Series ficticias explícitas y gráficos SVG propios; sin motor gráfico ni dependencias. */
const PanelInsights = (() => {
  const E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const sum=(list,key)=>list.reduce((n,r)=>n+(r[key]||0),0);
  const pct=(a,b)=>b?Math.round(a/b*100):0;
  const hours=n=>(n/60).toLocaleString('es-CO',{maximumFractionDigits:1,minimumFractionDigits:1});
  const shortDate=s=>s.slice(8,10)+'/'+s.slice(5,7);
  const tiers=['Essential','Pro','Business'];
  function prepare(db){
    for(const u of db.users){
      if(!tiers.includes(u.tier))u.tier=tiers[(Number(u.id.split('-')[1])||0)%3];
      if(u.insights)continue;
      const n=Number(u.id.split('-')[1]);
      if(!Number.isInteger(n)||n<1||n>(u.tenant==='azc'?24:12)||!['azc','atlas'].includes(u.tenant)){u.insights={days:[],episodes:[],leaves:[],mode:'Sede',planned:480};continue;}
      const mode=n%4===0?'Remoto':'Sede',days=[];
      for(let i=0;i<30;i++){
        const date=new Date(Date.UTC(2026,7,18+i)),stamp=date.toISOString().slice(0,10),weekday=date.getUTCDay(),weekend=weekday===0||weekday===6,today=i===29;
        const status=weekend?'No programado':today&&n%11===0?'Permiso':(i+n)%23===0?'Ausente':'Presente';
        const rest=status==='Presente'?(today?5+(n%3)*5:35+n%4*5):0;
        const active=status==='Presente'?(today?70+n%4*3:350+(n*13+i*7)%85):0;
        const productive=Math.round(active*(.68+(n*3+i)%23/100)),focused=Math.round(productive*(.74+(n+i)%17/100));
        days.push({date:stamp,status,rest,active,productive,nonproductive:active-productive,focused,checkin:status==='Presente'?'08:'+String((n*3+i)%15).padStart(2,'0'):null,place:mode==='Remoto'?'Remoto · '+u.site:u.site+' · oficina'});
      }
      u.insights={mode,planned:480,days,episodes:[{at:'09:27',app:'Word',window:'Informe de seguimiento.docx',duration:15,classification:'Productivo',source:'window_episode'},{at:'09:12',app:'Edge',window:'Portal documental de la empresa',duration:15,classification:'Productivo',source:'window_episode'},{at:'09:07',app:'Pausa',window:'Sin entrada de teclado o ratón',duration:5,classification:'Descanso',source:'logs'},{at:'08:52',app:'Outlook',window:'Bandeja de entrada corporativa',duration:15,classification:'Productivo',source:'window_episode'}],leaves:n%11===0?[{kind:'Permiso personal',date:'16 sep 2026',status:'Aprobado',duration:'1 día'}]:[{kind:'Vacaciones',date:'5 a 9 oct 2026',status:'Solicitado',duration:'5 días'}]};
    }
    if(!db.demoFeed)db.demoFeed=[];
    return db;
  }
  function aggregate(users,period=7){
    const byDate=new Map();
    for(const u of users)for(const day of (u.insights?.days||[]).slice(-period)){
      if(!byDate.has(day.date))byDate.set(day.date,{date:day.date,active:0,productive:0,nonproductive:0,focused:0,rest:0,present:0,expected:0});
      const r=byDate.get(day.date);for(const key of ['active','productive','nonproductive','focused','rest'])r[key]+=day[key];r.present+=Number(day.status==='Presente');r.expected+=Number(day.status!=='No programado');
    }
    const days=[...byDate.values()].sort((a,b)=>a.date.localeCompare(b.date));
    const active=sum(days,'active'),productive=sum(days,'productive'),focused=sum(days,'focused');
    return {days,active,productive,nonproductive:active-productive,focused,score:pct(productive,active),focus:pct(focused,active),presence:pct(sum(days,'present'),sum(days,'expected')),present:sum(days,'present'),expected:sum(days,'expected')};
  }
  const badge=u=>`<span class="v-tier">Tier ${E(u.tier||'Essential')}</span>`;
  const noData=message=>`<p class="v-chart-empty">${message||'Todavía no hay actividad registrada. Espera la primera sincronización del agente.'}</p>`;
  function line(id,title,labels,values,{unit='h',max,description=''}={}){
    if(!values.some(v=>v!==null&&v!==undefined))return noData();
    const upper=max||Math.max(1,Math.ceil(Math.max(...values.filter(v=>v!==null))/10)*10);
    const draw=(width,height,narrow)=>{
      const left=43,right=15,top=28,bottom=40,w=width-left-right,h=height-top-bottom;
      const x=i=>left+i*w/Math.max(1,values.length-1),y=v=>top+h-v/upper*h;
      const points=values.flatMap((v,i)=>v===null||v===undefined?[]:[{x:x(i),y:y(v),v,i}]);
      let path='',last=-2;for(const p of points){path+=(p.i===last+1?' L ':' M ')+p.x.toFixed(2)+' '+p.y.toFixed(2);last=p.i;}
      const groups=[];for(const p of points){if(!groups.length||p.i!==groups.at(-1).at(-1).i+1)groups.push([]);groups.at(-1).push(p);}
      const area=groups.map(group=>`M ${group[0].x} ${y(0)} ${group.map(p=>`L ${p.x} ${p.y}`).join(' ')} L ${group.at(-1).x} ${y(0)} Z`).join(' ');
      const ticks=values.length>7?[0,Math.floor(values.length/3),Math.floor(values.length*2/3),values.length-1]:labels.map((_,i)=>i);
      const key=id+(narrow?'-mobile':'-wide');
      return `<svg class="v-chart-svg ${narrow?'v-chart-mobile':'v-chart-wide'}" viewBox="0 0 ${width} ${height}" role="img" aria-labelledby="${key}-title ${key}-desc"><title id="${key}-title">${E(title)}</title><desc id="${key}-desc">${E(description)} ${labels.map((l,i)=>l+': '+(values[i]===null?'sin dato':Number(values[i]).toFixed(1)+' '+unit)).join('; ')}.</desc>${[0,.5,1].map(f=>`<path class="v-axis-grid" d="M ${left} ${y(upper*f)} H ${width-right}"/><text x="${left-9}" y="${y(upper*f)+5}" text-anchor="end">${Number((upper*f).toFixed(1))}</text>`).join('')}<text x="${left}" y="17">${unit==='%'?'Porcentaje (%)':'Horas (h)'}</text>${area?`<path d="${area}" class="v-area-fill"/>`:''}<path d="${path}" class="v-series-line"/>${points.map(p=>`<circle cx="${p.x}" cy="${p.y}" r="${values.length>7?2.5:4}" class="v-series-point"/>`).join('')}${ticks.map(i=>`<text x="${x(i)}" y="${height-12}" text-anchor="${i===0?'start':i===values.length-1?'end':'middle'}">${E(labels[i])}</text>`).join('')}</svg>`;
    };
    return `<figure class="v-chart" data-chart="line">${draw(640,270,false)}${draw(320,220,true)}<figcaption>${E(description)}</figcaption><details class="v-chart-values"><summary>Ver valores de ${E(title.toLowerCase())}</summary><ul>${labels.map((l,i)=>`<li><span>${E(l)}</span><strong>${values[i]===null?'Sin dato aún':Number(values[i]).toLocaleString('es-CO',{maximumFractionDigits:1})+' '+unit}</strong></li>`).join('')}</ul></details></figure>`;
  }
  function donut(id,title,parts,center,sub){
    const total=sum(parts,'value');if(!total)return noData();
    const r=73,circ=2*Math.PI*r;let offset=0;
    const circles=parts.map((p,i)=>{const length=p.value/total*circ;const html=`<circle cx="110" cy="110" r="${r}" class="v-donut-segment v-series-${i}" fill="none" stroke-width="26" stroke-dasharray="${Math.max(0,length-5)} ${circ-Math.max(0,length-5)}" stroke-dashoffset="${-offset}" transform="rotate(-90 110 110)"/>`;offset+=length;return html;}).join('');
    return `<figure class="v-donut" data-chart="donut"><svg viewBox="0 0 220 220" role="img" aria-labelledby="${id}-title ${id}-desc"><title id="${id}-title">${E(title)}</title><desc id="${id}-desc">${parts.map(p=>E(p.label)+': '+pct(p.value,total)+'%').join('; ')}.</desc>${circles}<text x="110" y="111" text-anchor="middle" class="v-donut-number">${E(center)}</text><text x="110" y="136" text-anchor="middle">${E(sub)}</text></svg><figcaption><ol class="v-chart-legend">${parts.map((p,i)=>`<li><span class="v-key v-series-${i}" aria-hidden="true"></span><span>${E(p.label)}</span><strong>${pct(p.value,total)}%</strong></li>`).join('')}</ol></figcaption></figure>`;
  }
  function gauge(id,value){
    const angle=Math.PI*(1-value/100),x=120+86*Math.cos(angle),y=116-86*Math.sin(angle);
    return `<figure class="v-gauge" data-chart="gauge"><svg viewBox="0 0 240 160" role="img" aria-labelledby="${id}-title ${id}-desc"><title id="${id}-title">Focus Score: ${value} de 100</title><desc id="${id}-desc">Porcentaje del tiempo activo en bloques de concentración de 25 minutos o más. Escala de 0 a 100.</desc><path class="v-gauge-track" d="M34 116 A86 86 0 0 1 206 116"/><path class="v-gauge-fill" d="M34 116 A86 86 0 ${value>100?1:0} 1 ${x} ${y}"/><text x="120" y="108" text-anchor="middle" class="v-donut-number">${value}</text><text x="120" y="135" text-anchor="middle">de 100</text><text x="22" y="150">0</text><text x="198" y="150">100</text></svg><figcaption>Minutos en concentración / minutos activos. Descansos excluidos.</figcaption></figure>`;
  }
  function bar(id,label,value,detail=''){
    return `<div class="v-person-bar" data-value="${value}"><div><span>${label}</span><strong>${value}%</strong></div><svg viewBox="0 0 300 12" role="img" aria-labelledby="${id}-title"><title id="${id}-title">${E(label.replace(/<[^>]*>/g,''))}: ${value} por ciento. ${E(detail)}</title><rect x="1" y="1" width="298" height="10" rx="3" class="v-bar-track"/><rect x="1" y="1" width="${298*value/100}" height="10" rx="3" class="v-bar-fill"/></svg>${detail?`<p>${E(detail)}</p>`:''}</div>`;
  }
  function kpis(items,icon){return `<dl class="v-kpi-register">${items.map(([label,value,detail,i])=>`<div><dt>${icon(i)}${label}</dt><dd><span>${value}</span><p>${detail}</p></dd></div>`).join('')}</dl>`;}
  function definitions(){return `<details class="v-metric-help"><summary>Cómo leer productividad y Focus Score</summary><p><strong>Productividad:</strong> minutos en apps clasificadas como productivas / minutos activos. <strong>Focus Score:</strong> minutos productivos en bloques de 25 minutos o más / minutos activos. Ambos excluyen descansos.</p><p>Clasificación ficticia para esta demostración. No equivale a horas trabajadas ni evalúa el desempeño de una persona.</p></details>`;}
  function dashboard({db,c,D,U,can,head,link,icon,url,button}){
    const team=U.filter(u=>u.active),week=aggregate(team,3),today=team.map(u=>({u,d:u.insights?.days.at(-1)})).filter(({d})=>d?.date==='2026-09-16'),online=D.filter(d=>d.online).length;
    const rows=D.filter(d=>!d.online&&d.days>7),pending=D.filter(d=>d.policy==='Pendiente'),hasReports=can('reportes.ver');
    let html=head('Tu equipo, de un vistazo',`${E(db.tenants.find(t=>t.id===c.tenant).name)} · Miércoles, 16 sep · 09:42 COT · Datos ficticios`,can('equipos.ver')?link('Revisar equipos','equipos',{},true,'equipos'):'');
    html+=kpis([['Equipos en línea',`${online}<small> / ${D.length}</small>`,'Conexión del agente ahora','equipos'],...(hasReports?[['Horas esta semana',hours(week.active)+'<small> h</small>','Lun 14 a hoy · tiempo activo','reportes'],['Productividad del equipo',week.active?week.score+'<small>%</small>':'Sin datos',week.active?'Focus Score '+week.focus+'/100 · esta semana':'Espera la primera sincronización','usuarios']]:[]),['Cumplimiento de reglas',D.length?pct(D.filter(d=>d.policy==='Aplicada').length,D.length)+'<small>%</small>':'Sin equipos',pending.length+' equipos con revisión pendiente','reglas']],icon);
    html+=`<section class="v-alert-band"><div><h2>${rows.length?rows.length+' equipos necesitan revisión':'Sin desconexiones prolongadas'}</h2><p>${rows.length?'Llevan más de 7 días sin conectarse. Confirma que sigan en uso.':'Ningún equipo supera 7 días sin conexión.'}</p></div><div class="v-alert-links">${rows.slice(0,3).map(d=>can('equipos.ver')?link(d.host+' · '+d.days+' días','equipo',{id:d.id}):`<p>${d.days} días sin conexión. Solicita revisión a IT.</p>`).join('')}</div>${pending.length?`<p>${pending.length} equipos recibirán las reglas pendientes al reconectarse. ${can('equipos.ver')?`<a href="${url('equipos',{connection:'offline'})}">Revisar conexión de equipos</a>`:''}</p>`:''}</section>`;
    if(hasReports){
      const values=['2026-09-14','2026-09-15','2026-09-16','2026-09-17','2026-09-18','2026-09-19','2026-09-20'].map(date=>{const d=week.days.find(d=>d.date===date);return d?d.active/60:null;});
      const areas=[...new Set(team.map(u=>u.area))].map(area=>({label:area,value:aggregate(team.filter(u=>u.area===area),3).active}));
      html+=`<div class="v-insight-grid v-section"><section class="work-surface"><div class="v-chart-heading"><div><h2>Salida semanal</h2><p>Horas activas por día · 14 a 20 sep</p></div><strong>${hours(week.active)}<small> h acumuladas</small></strong></div>${line('home-week','Salida semanal',['Lun','Mar','Mié','Jue','Vie','Sáb','Dom'],values,{description:'Miércoles parcial, corte 09:42. Los días futuros aún no tienen datos.'})}</section><section class="v-side-chart"><h2>Carga por área / proceso</h2><p>Cómo se distribuye el tiempo activo de esta semana.</p>${donut('home-area','Carga por área',areas,String(areas.filter(a=>a.value).length),'áreas')}</section></div>${definitions()}`;
      html+=`<div class="v-people-grid v-section"><section><div class="v-sectionhead"><div><h2>Roster de hoy</h2><p>Utilización del tiempo desde el check-in, hasta las 09:42.</p></div>${can('usuarios.ver')||can('usuarios.gestionar')?link('Ver personas','usuarios',{},false,'usuarios'):''}</div>${today.length?today.slice(0,6).map(({u,d},i)=>{const elapsed=d.checkin?102-Number(d.checkin.slice(3)):0;return bar('roster-'+i,`<a href="${url('miembro',{id:u.id})}">${E(u.name)}</a>`,pct(d.active,elapsed),d.status==='Presente'?`${u.insights.mode} · ${hours(d.active)} h activas · entrada ${d.checkin}`:d.status);}).join(''):noData('Todavía no hay check-ins de hoy. Espera la primera conexión de las personas asignadas.')}</section>${feed(db,c,U,can,button,url)}</div>`;
    }else html+=feed(db,c,U,can,button,url);
    html+=`<section class="v-section"><h2>Acciones rápidas</h2><div class="v-actions">${can('equipos.agregar')?link('Agregar un equipo','equipos',{enroll:'1'},false,'plus'):''}${can('usuarios.gestionar')?link('Asignar una persona','usuarios',{},false,'usuarios'):''}${hasReports?link('Leer reportes','reportes',{},false,'reportes'):''}</div></section>`;
    return html;
  }
  function feed(db,c,users,can,button,url){
    const visible=new Set(users.map(u=>u.id)),live=db.demoFeed.filter(e=>e.tenant===c.tenant&&visible.has(e.user));
    const sample=users.filter(u=>u.insights?.days.at(-1)?.checkin).slice(0,3).map((u,i)=>({at:['09:42','09:27','09:12'][i],text:['Agente conectado y disponible','Bloque de actividad de Word recibido','Check-in de hoy sincronizado'][i],user:u.id}));
    return `<section class="v-activity-feed"><div class="v-sectionhead"><div><h2>Actividad en vivo</h2><p>Simulación local · sin actualización automática.</p></div></div><ol class="v-timeline">${[...live,...sample].slice(0,5).map(e=>`<li><time>${E(e.at)}</time><div><strong>${E(e.text)}</strong><p>${can('usuarios.ver')||can('usuarios.gestionar')||can('reportes.ver')?`<a href="${url('miembro',{id:e.user})}">${E(users.find(u=>u.id===e.user)?.name)}</a>`:'Equipo de tu alcance'}</p></div></li>`).join('')||'<li>No hay eventos todavía. Conecta el primer equipo para comenzar.</li>'}</ol>${users.length?button('Simular siguiente evento','feed-next',false,'','reportes'):''}${db.audit.filter(a=>a.tenant===c.tenant).length?`<details><summary>Últimas acciones administrativas</summary><ul>${db.audit.filter(a=>a.tenant===c.tenant).slice(0,3).map(a=>`<li>${E(a.when)} · ${E(a.what)}</li>`).join('')}</ul></details>`:''}</section>`;
  }
  function reports({db,c,U,query,head,button,url}){
    const period=query.period==='30'?30:7,s=aggregate(U,period),rank=U.map(u=>({u,s:aggregate([u],period)})).filter(r=>r.s.active).sort((a,b)=>b.s.score-a.s.score),today=U.map(u=>u.insights?.days.at(-1)).filter(d=>d?.date==='2026-09-16');
    let html=head('Productividad y presencia',`${E(db.tenants.find(t=>t.id===c.tenant).name)} · ${period} días hasta el 16 sep, 09:42 · Datos ficticios`,s.active?button('Exportar reporte CSV','export',true,'','reportes'):'');
    html+=`<nav class="v-periods" aria-label="Periodo del reporte"><a href="${url('reportes',{period:'7'})}" ${period===7?'aria-current="page"':''}>Últimos 7 días</a><a href="${url('reportes',{period:'30'})}" ${period===30?'aria-current="page"':''}>Últimos 30 días</a></nav>`;
    if(!s.active)return html+`<section class="work-surface"><h2>Aún no hay actividad para reportar</h2><p>Espera la primera sincronización del agente. El reporte mostrará solo personas de tu empresa y alcance.</p></section>`;
    const working=s.days.filter(d=>d.active),delta=working.length>1?pct(working.at(-1).productive,working.at(-1).active)-pct(working[0].productive,working[0].active):0;
    html+=`<div class="v-insight-grid v-section"><section class="work-surface"><div class="v-chart-heading"><div><h2>Tendencia de productividad</h2><p>${delta>=0?'+':''}${delta} puntos frente al primer día con actividad del periodo.</p></div><strong>${s.score}<small>% del periodo</small></strong></div>${line('report-trend','Tendencia de productividad',s.days.map(d=>shortDate(d.date)),s.days.map(d=>d.active?pct(d.productive,d.active):null),{unit:'%',max:100,description:'Porcentaje diario de actividad productiva. Un día sin actividad deja un hueco, no un cero.'})}</section><section class="v-side-chart"><h2>Productivo vs no productivo</h2><p>${hours(s.active)} h activas clasificadas en el periodo.</p>${donut('report-productivity','Productivo vs no productivo',[{label:'Productivo',value:s.productive},{label:'No productivo',value:s.nonproductive}],s.score+'%','productivo')}</section></div>${definitions()}`;
    html+=`<div class="v-people-grid v-section"><section><h2>Ranking por productividad</h2><p>Ordenado por porcentaje de apps productivas. ${rank.length} personas con actividad; no es una evaluación de desempeño.</p><p class="v-bar-scale"><span>0%</span><span>50%</span><span>100%</span></p>${rank.slice(0,8).map(({u,s},i)=>bar('ranking-'+i,`<a href="${url('miembro',{id:u.id})}">${i+1}. ${E(u.name)}</a>`,s.score,`${hours(s.active)} h activas · Focus Score ${s.focus}/100`)).join('')}${rank.length>8?`<details class="v-more-people"><summary>Ver las ${rank.length-8} personas restantes</summary>${rank.slice(8).map(({u,s},i)=>bar('ranking-more-'+i,`<a href="${url('miembro',{id:u.id})}">${i+9}. ${E(u.name)}</a>`,s.score,hours(s.active)+' h activas')).join('')}</details>`:''}</section><section><h2>Presencia y asistencia</h2><p class="v-big">${s.presence}<small>% de jornadas programadas con check-in</small></p><p>${s.present} de ${s.expected} jornadas programadas. Un check-in confirma registro de acceso; no demuestra trabajo continuo.</p>${line('attendance','Asistencia diaria',s.days.map(d=>shortDate(d.date)),s.days.map(d=>d.expected?pct(d.present,d.expected):null),{unit:'%',max:100,description:'Jornadas con check-in / jornadas programadas. Días no programados sin dato.'})}<dl class="v-attendance-today"><div><dt>Check-ins hoy</dt><dd>${today.filter(d=>d.status==='Presente').length}</dd></div><div><dt>Ausencias / permisos hoy</dt><dd>${today.filter(d=>['Ausente','Permiso'].includes(d.status)).length}</dd></div></dl></section></div>`;
    return html;
  }
  function member({db,c,D,U,query,can,head,link,button,icon,url}){
    const u=U.find(u=>u.id===query.id)||(!query.id?U[0]:null);if(!u)return head('Persona no disponible','La persona no existe en tu empresa o está fuera de tu alcance.')+link('Volver a Usuarios','usuarios');
    const data=u.insights,s=aggregate([u],7),today=data.days.find(d=>d.date==='2026-09-16'),devices=D.filter(d=>d.user===u.id),read=can('reportes.ver');
    const tabs=[['resumen','Resumen'],...((read||can('diagnostico.ver'))?[['actividad','Actividad y registros']]:[]),...(can('usuarios.gestionar')?[['rrhh','RRHH y ausencias']]:[]),...(can('equipos.ver')?[['acceso','Acceso y dispositivos']]:[])];
    const requested=query.tab||'resumen',tab=tabs.some(([id])=>id===requested)?requested:null;
    let html=head(u.name,`${E(u.job)} · ${E(u.area)} · ${E(u.site)} / ${E(data.mode)}${u.active?'':' · Baja registrada'}`);
    html+=`<div class="v-member-context">${badge(u)}<p><strong>Check-in de hoy:</strong> ${today?.checkin?`${today.checkin} · ${E(today.place)}`:today?.status==='Permiso'?'Permiso aprobado · sin check-in':'Sin registro todavía'} · Datos ficticios</p></div>`;
    if(read)html+=kpis([['Primer login hoy',today?.checkin||'Sin registro','Hora Colombia (UTC−5)','lock'],['Tiempo de descanso',today?today.rest+'<small> min</small>':'Sin datos','Pausas registradas hoy','ajustes'],['Horas hoy',today?hours(today.active)+'<small> h</small>':'Sin datos','Actividad hasta las 09:42','reportes'],['Productividad',today?.active?pct(today.productive,today.active)+'<small>%</small>':'Sin datos','Apps productivas / actividad de hoy','usuarios']],icon);
    html+=`<nav class="v-member-tabs" aria-label="Vistas de ${E(u.name)}">${tabs.map(([id,label])=>`<a href="${url('miembro',{id:u.id,tab:id})}" ${tab===id?'aria-current="page"':''}>${label}</a>`).join('')}</nav>`;
    if(!tab)return html+'<section class="v-notice"><h2>Esta vista necesita otro permiso</h2><p>Vuelve a Resumen o solicita acceso al administrador de tu empresa.</p></section>';
    if(tab==='resumen'){
      html+=`<div class="v-member-overview"><section class="work-surface"><h2>Equipo asignado</h2>${can('equipos.ver')?(devices.length?devices.map(d=>`<article class="v-member-device"><h3><a href="${url('equipo',{id:d.id})}">${E(d.host)}</a></h3><p>${d.online?'En línea':'Sin conexión'} · ${E(d.state)} · Agente ${d.version}</p><dl class="v-facts"><dt>Modelo</dt><dd>Dell Latitude 5450</dd><dt>Sistema</dt><dd>Windows 11 Pro · 24H2</dd><dt>Procesador / RAM</dt><dd>Intel Core Ultra 5 · 16 GB</dd><dt>Disco</dt><dd>SSD 512 GB · 186 GB libres</dd></dl></article>`).join(''):noData('Esta persona aún no tiene equipo. Asígnalo desde Usuarios.')):'<p>Solicita a IT la ficha del equipo asignado.</p>'}</section><section><h2>Historial de check-in</h2><p>Últimos cinco días programados · hora Colombia.</p>${read||can('usuarios.gestionar')?`<ol class="v-checkins">${data.days.filter(d=>d.status!=='No programado').slice(-5).reverse().map(d=>`<li><strong>${shortDate(d.date)}</strong><span>${d.checkin||d.status}</span><small>${E(d.place)}</small></li>`).join('')||'<li>Aún no hay registros. Espera la primera conexión.</li>'}</ol>`:'<p>Tu cuenta no tiene permiso de reportes para consultar asistencia.</p>'}</section></div>`;
      if(read)html+=`<section class="v-section work-surface"><div class="v-chart-heading"><div><h2>Tendencia 7 días</h2><p>Horas activas diarias de ${E(u.name)}.</p></div><strong>${hours(s.active)}<small> h registradas</small></strong></div>${line('member-week','Tendencia de 7 días',s.days.map(d=>shortDate(d.date)),s.days.map(d=>d.active/60),{description:'Últimos 7 días hasta hoy, 09:42. Cero indica que no se registró actividad.'})}</section><div class="v-member-meters v-section"><section><h2>Focus Score</h2>${s.active?gauge('member-focus',s.focus):noData()}</section><section><h2>Productividad</h2><p>Distribución del tiempo activo · últimos 7 días.</p>${donut('member-productivity','Productividad de '+u.name,[{label:'Productivo',value:s.productive},{label:'No productivo',value:s.nonproductive}],s.score+'%','productivo')}</section></div>${definitions()}`;
    }
    if(tab==='actividad')html+=`<section class="work-surface"><h2>Actividad y registros</h2><p>Muestra de apps, ventanas y eventos. Datos ficticios; no hay captura de un equipo real.</p><ol class="v-timeline">${today?.checkin?data.episodes.map(e=>`<li><time>${e.at}</time><div><h3>${E(e.app)} · ${e.duration} min</h3><p>${E(e.window)}</p><p>${E(e.classification)} · Registro de ${e.source==='window_episode'?'ventana activa':'evento del agente'}</p></div></li>`).join(''):'<li>No hay actividad hoy. Revisa el próximo check-in o la conexión del equipo.</li>'}</ol><details><summary>Correspondencia técnica de estos ejemplos</summary><p>Las ventanas representan <code>window_episode</code>; check-in, pausas y comandos representan <code>logs</code>. Es una correspondencia conceptual para diseño, no un contrato de API.</p></details></section>`;
    if(tab==='rrhh')html+=`<section class="work-surface"><h2>RRHH y ausencias</h2><p>Vista de ejemplo de vacaciones y permisos. La solicitud y aprobación no están conectadas en este prototipo.</p><ul class="v-leave-list">${data.leaves.map(l=>`<li><h3>${E(l.kind)}</h3><p>${E(l.date)} · ${l.duration}</p><strong>${E(l.status)} (muestra)</strong></li>`).join('')||'<li>No hay ausencias de ejemplo para esta persona. Consulta con RRHH antes de registrar cambios.</li>'}</ul></section>`;
    if(tab==='acceso')html+=`<section class="work-surface"><h2>Acceso y dispositivos</h2><p>${u.active?'Persona activa':'Persona dada de baja'} · Rol ${E(db.roles.find(r=>r.id===u.role)?.name||'Colaborador')}. ${db.roles.find(r=>r.id===u.role)?.panel===false?'Sin login al panel en v4.0.':''}</p>${devices.length?devices.map((d,i)=>`<article class="v-member-device"><h3>${E(d.host)}</h3><p role="status"><strong>${d.pending?'Comando en cola: '+d.pending.action:E(d.state)}</strong> · ${d.online?'En línea':'Sin conexión'} · ${d.last}</p><p>Windows 11 Pro · 16 GB RAM · Agente ${d.version}</p><div class="v-actions">${can('equipos.accionar')&&!d.pending&&d.state!=='Borrado'?[d.state==='Bloqueado'?'desbloquear':'bloquear','apagar'].filter(action=>can('equipos.'+action)).map((action,j)=>button({bloquear:'Bloquear equipo',desbloquear:'Desbloquear equipo',apagar:'Apagar equipo'}[action],'command',i===0&&j===0,`data-id="${d.id}" data-command="${action}"`,'lock')).join(''):''}${link('Ver ficha y cronología','equipo',{id:d.id})}${d.pending&&can('equipos.accionar')&&can('equipos.'+d.pending.action)?button('Simular respuesta del agente','agent',false,`data-id="${d.id}"`):''}</div>${d.pending?'<p>Esperando confirmación del equipo. La solicitud se aplicará cuando el agente se conecte.</p>':''}</article>`).join(''):noData('Sin dispositivos asignados. Vincula un equipo desde Usuarios.')}</section>`;
    return html;
  }
  function exportRows(users,period){
    const s=aggregate(users,period);
    return [['Fecha','Horas activas','Horas productivas','Productividad %','Focus Score','Check-ins','Jornadas programadas'],...s.days.map(d=>[d.date,hours(d.active),hours(d.productive),d.active?pct(d.productive,d.active):'',d.active?pct(d.focused,d.active):'',d.present,d.expected])];
  }
  return {prepare,aggregate,badge,line,donut,gauge,bar,dashboard,reports,member,exportRows};
})();
