  try{const stored=localStorage.getItem(key);if(stored)db=JSON.parse(stored);}catch{}
  if(!db.catalog.some(p=>p.key==='hardening.gestionar'))db.catalog.push(M.fresh().catalog.find(p=>p.key==='hardening.gestionar'));
